#include "odbc_connector.h"
#include <stdio.h>
#include <string.h>
static void err(sleela_odbc*c,const char*m){if(c)snprintf(c->error,sizeof c->error,"%s",m?m:"ODBC error");}
static void diag(sleela_odbc*c,SQLSMALLINT type,SQLHANDLE h,const char*fallback){SQLCHAR state[6]={0},msg[400]={0};SQLINTEGER native=0;SQLSMALLINT n=0;if(SQL_SUCCEEDED(SQLGetDiagRec(type,h,1,state,&native,msg,sizeof msg,&n)))err(c,(const char*)msg);else err(c,fallback);}
int sleela_odbc_connect(sleela_odbc*c,const char*cs){if(!c||!cs)return 0;memset(c,0,sizeof *c);SQLRETURN r=SQLAllocHandle(SQL_HANDLE_ENV,SQL_NULL_HANDLE,&c->env);if(!SQL_SUCCEEDED(r)){err(c,"SQLAllocHandle ENV failed");goto fail;}SQLSetEnvAttr(c->env,SQL_ATTR_ODBC_VERSION,(SQLPOINTER)SQL_OV_ODBC3,0);r=SQLAllocHandle(SQL_HANDLE_DBC,c->env,&c->dbc);if(!SQL_SUCCEEDED(r)){err(c,"SQLAllocHandle DBC failed");goto fail;}SQLCHAR out[1024];SQLSMALLINT outlen=0;r=SQLDriverConnect(c->dbc,NULL,(SQLCHAR*)cs,SQL_NTS,out,sizeof out,&outlen,SQL_DRIVER_NOPROMPT);if(!SQL_SUCCEEDED(r)){diag(c,SQL_HANDLE_DBC,c->dbc,"ODBC driver connection failed");goto fail;}return 1;fail:sleela_odbc_close(c);return 0;}
void sleela_odbc_close(sleela_odbc*c){if(!c)return;if(c->stmt){SQLFreeHandle(SQL_HANDLE_STMT,c->stmt);c->stmt=SQL_NULL_HSTMT;}if(c->dbc){SQLDisconnect(c->dbc);SQLFreeHandle(SQL_HANDLE_DBC,c->dbc);c->dbc=SQL_NULL_HDBC;}if(c->env){SQLFreeHandle(SQL_HANDLE_ENV,c->env);c->env=SQL_NULL_HENV;}}
const char*sleela_odbc_error(const sleela_odbc*c){return c?c->error:"invalid connector";}
static int new_stmt(sleela_odbc*c){if(c->stmt){SQLFreeHandle(SQL_HANDLE_STMT,c->stmt);c->stmt=SQL_NULL_HSTMT;}if(!SQL_SUCCEEDED(SQLAllocHandle(SQL_HANDLE_STMT,c->dbc,&c->stmt))){err(c,"ODBC statement allocation failed");return 0;}return 1;}
int sleela_odbc_exec(sleela_odbc*c,const char*sql){if(!c||!c->dbc||!sql)return 0;if(!new_stmt(c))return 0;SQLRETURN r=SQLExecDirect(c->stmt,(SQLCHAR*)sql,SQL_NTS);if(!SQL_SUCCEEDED(r)){diag(c,SQL_HANDLE_STMT,c->stmt,"ODBC SQL execution failed");return 0;}return 1;}
int sleela_odbc_prepare(sleela_odbc*c,const char*sql){if(!c||!c->dbc||!sql)return 0;if(!new_stmt(c))return 0;SQLRETURN r=SQLPrepare(c->stmt,(SQLCHAR*)sql,SQL_NTS);if(!SQL_SUCCEEDED(r)){diag(c,SQL_HANDLE_STMT,c->stmt,"ODBC prepare failed");return 0;}return 1;}
int sleela_odbc_execute_prepared(sleela_odbc*c){if(!c||!c->stmt)return 0;SQLRETURN r=SQLExecute(c->stmt);if(!SQL_SUCCEEDED(r)){diag(c,SQL_HANDLE_STMT,c->stmt,"ODBC prepared execution failed");return 0;}return 1;}
SQLRETURN sleela_odbc_fetch(sleela_odbc*c){if(!c||!c->stmt)return SQL_INVALID_HANDLE;SQLRETURN r=SQLFetch(c->stmt);if(!SQL_SUCCEEDED(r)&&r!=SQL_NO_DATA)diag(c,SQL_HANDLE_STMT,c->stmt,"ODBC fetch failed");return r;}
SQLRETURN sleela_odbc_get_data(sleela_odbc*c,SQLUSMALLINT col,SQLSMALLINT type,SQLPOINTER buf,SQLLEN bytes,SQLLEN*ind){if(!c||!c->stmt)return SQL_INVALID_HANDLE;SQLRETURN r=SQLGetData(c->stmt,col,type,buf,bytes,ind);if(!SQL_SUCCEEDED(r)&&r!=SQL_NO_DATA)diag(c,SQL_HANDLE_STMT,c->stmt,"ODBC column read failed");return r;}
SQLHSTMT sleela_odbc_statement(sleela_odbc*c){return c?c->stmt:SQL_NULL_HSTMT;}
SQLLEN sleela_odbc_row_count(sleela_odbc*c){SQLLEN n=0;if(c&&c->stmt)SQLRowCount(c->stmt,&n);return n;}
